mapper.update:
UPDATE /* com.seinfo.protoA.component.proposal.mapper.updateProposal */
    seinfo_proposal
SET proposal_title     = LEFT(#{proposalTitle}, 100)
  , proposal_area      = #{proposalArea}
  , proposal_area_cont = LEFT(#{proposalAreaCont}, 100)
  , proposal_detail    = #{proposalDetail}
  , state_rtp          = #{stateRtp}
  , mod_dt             = now()
  , mod_user_id        = #{userEmail}
WHERE proposal_no = #{proposalNo}
  AND user_uid = (select user_uid from seinfo_vendor_manager a where a.user_email = #{userEmail}
                                                               and IFNULL(a.user_pwd_init_yn,'N') != 'Y'
                                                               and a.bl_yn = 'N'
)

mapper.delete:
DELETE /* com.seinfo.protoA.component.proposal.mapper.PpsMapper.deleteProposal */
FROM seinfo_proposal
WHERE proposal_no = #{proposalNo}
  AND user_uid = #{userUid}
  AND state_lrtp = #{stateLrtp}

mapper.select:
SELECT /* com.seinfo.protoA.component.proposal.mapper.PpsMapper.selectPpsFileGrpId */
    mfile_group_id as mfile_grp_id
FROM seinfo_proposal
WHERE proposal_no = #{proposalNo}
  AND user_uid = #{userUid}
  AND state_lrtp = #{stateLrtp}
